# Surah Al-Ma'ida (chapter 5) — part 9: ayat 81-90 (IDs 750-759)
SURAH = 5

ENTRIES = {
750: (
"اور اگر وہ — اللہ — نبیؐ — اور — جو ان کی طرف نازل کیا گیا — پر ایمان لاتے — تو وہ انہیں — دوست — نہیں بناتے — لیکن ان میں سے اکثر نافرمان ہیں",
"""۱۔ ایمان والے کافروں سے دوستی نہیں رکھتے — اگر وہ ایمان لاتے۔
۲۔ ’’وَلَوْ كَانُوا يُؤْمِنُونَ بِاللّٰہِ وَالنَّبِيِّ وَمَا أُنزِلَ إِلَيْهِ مَا اتَّخَذُوهُمْ أَوْلِيَاءَ‘‘ — اور اگر وہ — اللہ — نبیؐ — اور — جو ان کی طرف نازل کیا گیا — پر ایمان لاتے — تو وہ انہیں — دوست — نہیں بناتے — یعنی ایمان والے کافروں کو دوست نہیں بناتے۔
۳۔ ’’وَلَٰكِنَّ كَثِيرًا مِّنْهُمْ فَاسِقُونَ‘‘ — لیکن ان میں سے اکثر نافرمان ہیں — یعنی نافرمانی کی وجہ سے دوستی اختیار کرتے ہیں۔
۴۔ عملی سبق: کافروں سے دوستی نہ کرو؛ ایمان والوں کی دوستی اختیار کرو۔"""
),
751: (
"آپ ضرور پائیں گے کہ ایمان والوں کے سب سے زیادہ دشمن یہود اور مشرکین ہیں — اور آپ ضرور پائیں گے کہ — ان میں سے — جو لوگوں نے کہا ہم نصاریٰ ہیں — ان کو ایمان والوں سے سب سے زیادہ دوستی رکھنے والوں کے قریب پائیں گے — یہ اس لیے کہ ان میں — کچھ — رہبان (علماء) اور عبادت گزار ہیں اور یہ کہ وہ تکبر نہیں کرتے",
"""۱۔ یہود اور مشرکین — ایمان والوں کے سخت دشمن۔
۲۔ ’’لَتَجِدَنَّ أَشَدَّ النَّاسِ عَدَاوَۃً لِّلَّذِينَ آمَنُوا الْيَهُودَ وَالَّذِينَ أَشْرَكُوا‘‘ — آپ ضرور پائیں گے کہ ایمان والوں کے سب سے زیادہ دشمن یہود اور مشرکین ہیں — یعنی یہودیوں کا دشمنی سب سے شدید ہے۔
۳۔ ’’وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّۃً لِّلَّذِينَ آمَنُوا الَّذِينَ قَالُوا إِنَّا نَصَارَىٰ‘‘ — اور آپ ضرور پائیں گے کہ — ان میں سے — جو لوگوں نے کہا ہم نصاریٰ ہیں — ان کو ایمان والوں سے سب سے زیادہ دوستی رکھنے والوں کے قریب پائیں گے — یعنی نصاریٰ میں سے کچھ زیادہ نرم خو ہیں۔
۴۔ ’’ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ‘‘ — یہ اس لیے کہ ان میں — کچھ — رہبان (علماء) اور عبادت گزار ہیں اور یہ کہ وہ تکبر نہیں کرتے — یعنی رہبان اور علماء کی نرمی کی وجہ سے۔
۵۔ عملی سبق: یہود اور مشرکین سے محتاط رہو؛ نرم خو لوگوں کی قدر کرو۔"""
),
752: (
"اور جب وہ — جو رسول پر نازل کیا گیا ہے — سنتے ہیں تو آپ ان کی آنکھیں دیکھیں گے کہ — جو وہ حق سے — پہچانتے ہیں — اس کی وجہ سے — آنسو پھوٹ آتے ہیں — وہ کہتے ہیں: اے ہمارے رب! ہم ایمان لائے — پس ہمیں — گواہوں کے — ساتھ لکھ لے",
"""۱۔ اہلِ کتاب — قرآن سن کر روتے ہیں۔
۲۔ ’’وَإِذَا سَمِعُوا مَا أُنزِلَ إِلَى الرَّسُولِ تَرَىٰ أَعْيُنَهُمْ تَفِيضُ مِنَ الدَّمْعِ مِمَّا عَرَفُوا مِنَ الْحَقِّ‘‘ — اور جب وہ — جو رسول پر نازل کیا گیا ہے — سنتے ہیں تو آپ ان کی آنکھیں دیکھیں گے کہ — جو وہ حق سے — پہچانتے ہیں — اس کی وجہ سے — آنسو پھوٹ آتے ہیں — یعنی حق کو پہچان کر ان کی آنکھوں سے آنسو بہتے ہیں۔
۳۔ ’’يَقُولُونَ رَبَّنَا آمَنَّا فَاكْتُبْنَا مَعَ الشَّاهِدِينَ‘‘ — وہ کہتے ہیں: اے ہمارے رب! ہم ایمان لائے — پس ہمیں — گواہوں کے — ساتھ لکھ لے — یعنی ایمان کی گواہی دینے والوں کے ساتھ ہمارا نام لکھ۔
۴۔ عملی سبق: حق کو پہچاننے پر ایمان لاؤ؛ آنسو حق کی نشانی ہو سکتے ہیں۔"""
),
753: (
"اور ہمیں کیا ہو گیا کہ ہم اللہ پر اور — جو ہمارے پاس آیا ہے — حق پر — ایمان نہ لائیں — اور ہم طمع رکھتے ہیں کہ ہمارا رب ہمیں نیک لوگوں کے ساتھ داخل کرے",
"""۱۔ اہلِ کتاب — طمع رکھتے ہیں۔
۲۔ ’’وَمَا لَنَا لَا نُؤْمِنُ بِاللّٰہِ وَمَا جَاءَنَا مِنَ الْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ الْقَوْمِ الصَّالِحِينَ‘‘ — اور ہمیں کیا ہو گیا کہ ہم اللہ پر اور — جو ہمارے پاس آیا ہے — حق پر — ایمان نہ لائیں — اور ہم طمع رکھتے ہیں کہ ہمارا رب ہمیں نیک لوگوں کے ساتھ داخل کرے — یعنی ایمان اور طمع — دونوں ہیں۔
۳۔ عملی سبق: نیک لوگوں کے ساتھ شامل ہونے کی طمع رکھو؛ ایمان لاؤ۔"""
),
754: (
"پس انہیں — ان کی اس بات کی وجہ سے — اللہ نے — ایسی جنتیں جو نیچے سے نہریں بہتی ہیں — دیں — وہ ان میں ہمیشہ رہیں گے — اور یہی — نیکی کرنے والوں — کی جزا ہے",
"""۱۔ اللہ نے انہیں — جنتوں کا — انعام دیا۔
۲۔ ’’فَأَثَابَهُمُ اللّٰہُ بِمَا قَالُوا جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا‘‘ — پس انہیں — ان کی اس بات کی وجہ سے — اللہ نے — ایسی جنتیں جو نیچے سے نہریں بہتی ہیں — دیں — وہ ان میں ہمیشہ رہیں گے — یعنی سچا ایمان — ہمیشہ کی جنت۔
۳۔ ’’وَذَٰلِكَ جَزَاءُ الْمُحْسِنِينَ‘‘ — اور یہی — نیکی کرنے والوں — کی جزا ہے۔
۴۔ عملی سبق: احسان کرو؛ اللہ کے انعامات کی امید ہو۔"""
),
755: (
"اور جن لوگوں نے کفر کیا اور ہماری آیات جھٹلائیں — یہی آگ والے ہیں",
"""۱۔ کفار کا انجام — جہنم۔
۲۔ ’’وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا أُولَٰئِكَ أَصْحَابُ الْجَحِيمِ‘‘ — اور جن لوگوں نے کفر کیا اور ہماری آیات جھٹلائیں — یہی آگ والے ہیں — یعنی کفر اور تکذیب کا انجام جہنم ہے۔
۳۔ عملی سبق: آیات کو جھٹلاؤ مت؛ ایمان لاؤ۔"""
),
756: (
"اے ایمان والو! وہ پاکیزہ چیزیں — جو اللہ نے تمہارے لیے حلال کیں — حرام مت کرو — اور حد سے مت بڑھو — بے شک اللہ حد سے بڑھنے والوں سے محبت نہیں کرتا",
"""۱۔ حلال کو حرام مت کرو۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُحَرِّمُوا طَيِّبَاتِ مَا أَحَلَّ اللّٰہُ لَكُمْ وَلَا تَعْتَدُوا‘‘ — اے ایمان والو! وہ پاکیزہ چیزیں — جو اللہ نے تمہارے لیے حلال کیں — حرام مت کرو — اور حد سے مت بڑھو — یعنی اللہ کی حلال کردہ چیزوں کو حرام نہ قرار دو۔
۳۔ ’’إِنَّ اللّٰہَ لَا يُحِبُّ الْمُعْتَدِينَ‘‘ — بے شک اللہ حد سے بڑھنے والوں سے محبت نہیں کرتا — یعنی حلال کو حرام کہنا — اللہ کی حد سے تجاوز ہے۔
۴۔ عملی سبق: اللہ کی حلال کردہ چیزوں کو حرام مت کہو؛ اللہ کی حدود کی پابندی کرو۔"""
),
757: (
"اور کھاؤ اس میں سے جو اللہ نے تمہیں رزق دیا — حلال — پاکیزہ — اور اس اللہ سے ڈرو جس پر تم ایمان لاتے ہو",
"""۱۔ اللہ کا دیا ہوا رزق — حلال اور پاکیزہ۔
۲۔ ’’وَكُلُوا مِمَّا رَزَقَكُمُ اللّٰہُ حَلَالًا طَيِّبًا‘‘ — اور کھاؤ اس میں سے جو اللہ نے تمہیں رزق دیا — حلال — پاکیزہ — یعنی اللہ کا دیا ہوا رزق حلال اور پاکیزہ ہے۔
۳۔ ’’وَاتَّقُوا اللّٰہَ الَّذِي أَنتُم بِهِ مُّؤْمِنُونَ‘‘ — اور اس اللہ سے ڈرو جس پر تم ایمان لاتے ہو — یعنی تمہارے ایمان کا شکر ادا کرو۔
۴۔ عملی سبق: اللہ کا رزق حلال اور پاکیزہ سمجھو؛ اس پر شکر ادا کرو۔"""
),
758: (
"اللہ تمہیں تمہاری قسموں میں — فضول (چیز) میں — پکڑتا نہیں — لیکن وہ تمہیں — تمہاری قسموں — میں پکڑتا ہے جنہیں تم نے پختہ کر لیا — پس اس کا کفارہ ہے — دس مسکینوں کو کھانا کھلانا — جو تم اپنے گھر والوں کو کھلاتے ہو — اس کے اوسط (درمیانی) میں سے — یا انہیں کپڑے دینا — یا ایک غلام آزاد کرنا — پس جو کوئی نہ پائے تو تین دن کے روزے — یہ تمہاری قسموں کا کفارہ ہے — جب تم قسم اٹھاؤ — اور اپنی قسموں کی حفاظت کرو — اسی طرح اللہ تمہارے لیے اپنی آیات بیان کرتا ہے — شاید کہ تم شکر ادا کرو",
"""۱۔ فضول قسم — کوئی گناہ نہیں۔
۲۔ ’’لَّا يُؤَاخِذُكُمُ اللّٰہُ بِاللَّغْوِ فِي أَيْمَانِكُمْ‘‘ — اللہ تمہیں تمہاری قسموں میں — فضول (چیز) میں — پکڑتا نہیں — یعنی بے ارادہ قسم — گناہ نہیں۔
۳۔ ’’وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ الْأَيْمَانَ‘‘ — لیکن وہ تمہیں — تمہاری قسموں — میں پکڑتا ہے جنہیں تم نے پختہ کر لیا — یعنی ارادے اور پختگی والی قسم — ذمہ داری ہے۔
۴۔ ’’فَكَفَّارَتُهُ إِطْعَامُ عَشَرَۃِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَۃٍ‘‘ — پس اس کا کفارہ ہے — دس مسکینوں کو کھانا کھلانا — جو تم اپنے گھر والوں کو کھلاتے ہو — اس کے اوسط (درمیانی) میں سے — یا انہیں کپڑے دینا — یا ایک غلام آزاد کرنا — یعنی کفارہ — دس مسکینوں کو کھانا یا کپڑا یا غلام کی آزادی۔
۵۔ ’’فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَاثَۃِ أَيَّامٍ‘‘ — پس جو کوئی نہ پائے تو تین دن کے روزے — یعنی سہولت کے مطابق حل ہے۔
۶۔ ’’ذَٰلِكَ كَفَّارَۃُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ‘‘ — یہ تمہاری قسموں کا کفارہ ہے — جب تم قسم اٹھاؤ — اور اپنی قسموں کی حفاظت کرو — یعنی پختہ قسم کی ذمہ داری۔
۷۔ ’’كَذَٰلِكَ يُبَيِّنُ اللّٰہُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَشْكُرُونَ‘‘ — اسی طرح اللہ تمہارے لیے اپنی آیات بیان کرتا ہے — شاید کہ تم شکر ادا کرو۔
۸۔ عملی سبق: بے ارادہ قسم پر پریشان نہ ہو؛ پختہ قسم کی ذمہ داری پوری کرو۔"""
),
759: (
"اے ایمان والو! شراب — جوا — بت — اور قرعہ اندازی کے تیر — شیطان کے عمل کی گندگی (رجس) ہیں — پس — ان سے — بچ جاؤ — شاید کہ تم فلاح پاؤ",
"""۱۔ شراب اور جوا — حرام۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنصَابُ وَالْأَزْلَامُ رِجْسٌ مِّنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ‘‘ — اے ایمان والو! شراب — جوا — بت — اور قرعہ اندازی کے تیر — شیطان کے عمل کی گندگی (رجس) ہیں — پس — ان سے — بچ جاؤ — یعنی یہ سب شیطان کا کام ہیں — ان سے مکمل فاصلہ رکھو۔
۳۔ ’’لَعَلَّكُمْ تُفْلِحُونَ‘‘ — شاید کہ تم فلاح پاؤ — یعنی فلاح ان سے اجتناب سے ہے۔
۴۔ عملی سبق: شراب اور جوا سے مکمل پرہیز کرو؛ شیطان کے کاموں سے دور رہو۔"""
),
}
